UPDATE ai_mcp_token
   SET revoked_at = #{revokedAt},
       revoked_by = #{revokedBy}
 WHERE id = #{id}
   AND revoked_at IS NULL
   AND is_deleted = 0

UPDATE ai_mcp_token
   SET revoked_at = #{revokedAt},
       revoked_by = #{revokedBy}
 WHERE service_account_id = #{serviceAccountId}
   AND revoked_at IS NULL
   AND is_deleted = 0

UPDATE ai_mcp_token
   SET last_used_at = #{lastUsedAt}
 WHERE id = #{id}
   AND is_deleted = 0
